rows=[]
for m in re.finditer(r'\\begin\{result\}\{([^}]+)\}\{([^}]+)\}\{([^\n]+)\}\n(.*?)\\end\{result\}',tex,re.S):
    id,status,title,body=m.groups()
    dep,passage,read,notes=meta[id]
    body=re.sub(r'\\label\{[^}]+\}\s*','',body).strip()
    rows.append(dict(id=id,statement=title+' — '+body,status=status,where_proved='FLAGGED_149_paper.tex, statement '+id,depends_on=dep,manuscript_passages='cote 149; '+passage,depends_on_doubtful_reading=read,notes=notes))
assert len(rows)==22, len(rows)
(W/'AB_results.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
R=[]
